#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/checks.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Predicates the merge tasks ask before touching a branch"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# Each of these answers one question and returns a bool, so a caller reads as
# `if checks.has_untracked_files():`. They print NOTHING: the caller writes the
# text, because the same predicate is an error in one task and a note in
# another. The one exception is get_main_worktree_path, which returns a path.

import subprocess


def _git_out(*args):
  """The stdout of `git <args>` with the trailing newlines removed. The errors
  of git are not shown."""
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
  return result.stdout.rstrip("\n")


def _git_ok(*args):
  """Whether `git <args>` exits 0. No output is shown."""
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
  return result.returncode == 0


def has_uncommitted_changes():
  """Tracked files with changes, staged or not.

  `--ignore-submodules=dirty` skips changes IN a submodule: this repo tracks
  only the commit of a submodule, so a merge here can never carry them. A
  submodule moved to a new commit is still reported: that pointer is an
  uncommitted change of this repo.
  """
  result = subprocess.run(
    ["git", "status", "--porcelain", "--ignore-submodules=dirty"], check=False, stdout=subprocess.PIPE, text=True
  )
  return result.stdout.rstrip("\n") != ""


def has_untracked_files():
  """Files that git does not track and that .gitignore does not cover.

  Separate from the check above although `git status --porcelain` lists both:
  an untracked file is a different mistake from an uncommitted change (a
  branch switch leaves it behind instead of carrying it), and the two need
  different messages.
  """
  result = subprocess.run(
    ["git", "ls-files", "--others", "--exclude-standard"], check=False, stdout=subprocess.PIPE, text=True
  )
  return result.stdout.rstrip("\n") != ""


def is_local_branch(branch="HEAD"):
  """A branch with no upstream, so "unpushed" has nothing to compare with.
  The default is the current branch."""
  return not _git_ok("rev-parse", "--abbrev-ref", f"{branch}@{{u}}")


def has_unpushed_commits(branch="HEAD"):
  """Commits on ONE branch that its upstream does not have.

  Only for the branch, on purpose. The form for all the repo
  (`git log --branches --not --remotes`) answers a different question (does a
  local branch anywhere have unpushed work), and an unrelated experiment then
  refuses a merge that it has no relation to.
  """
  return _git_out("log", "--oneline", f"{branch}@{{u}}..{branch}") != ""


def branch_exists(branch):
  """A branch that exists here or on origin.

  The remote counts too: a fresh clone has only the default branch locally,
  and `git checkout <branch>` makes the local branch from origin when it runs.
  """
  return _git_ok("show-ref", "--verify", "--quiet", f"refs/heads/{branch}") or _git_ok(
    "show-ref", "--verify", "--quiet", f"refs/remotes/origin/{branch}"
  )


def is_git_worktree():
  """Whether this is a linked worktree and not the main checkout.

  This is important for a merge, because a branch checked out in one worktree
  cannot be checked out in another: a merge that runs from a linked worktree
  does its checkout in the main one. Outside a repo both git calls fail, and
  the answer is False.
  """
  return _git_out("rev-parse", "--git-dir") != _git_out("rev-parse", "--git-common-dir")


def get_main_worktree_path():
  """The absolute path of the main worktree, which `git worktree list` gives
  first. An empty string when git gives nothing."""
  result = subprocess.run(["git", "worktree", "list", "--porcelain"], check=False, stdout=subprocess.PIPE, text=True)
  lines = result.stdout.split("\n")
  if not result.stdout:
    return ""
  return lines[0].removeprefix("worktree ")
